('860000001', 'demo', '企业会员权益改版', '重新梳理企业会员的套餐权益、用量提示与管理员邀请路径，交付 PRD、流程图和验收指标。', '产品经理', '2026-06-03 09:30', '2026-06-12 18:00', '2026-06-12 16:40', '2026-06', 16, 14, 260, '林知夏', '周序', '顾言', '方案落地', '已验收', 100, '核心路径已上线灰度，指标埋点完整。', '[{"id":"demo-pm-1","date":"2026-06-04","start":"09:30","end":"17:30","note":"完成用户访谈归纳与权益信息架构"},{"id":"demo-pm-2","date":"2026-06-11","start":"10:00","end":"16:00","note":"完成 PRD 评审与验收清单","isAcceptanceProgress":true}]', '[]', 1, '2026-06-03 09:12', '2026-06-12 16:40'),
('860000002', 'demo', '企业控制台信息架构梳理', '针对多团队、多项目场景梳理控制台导航和权限可见性，输出站点地图与关键流程说明。', '产品经理', '2026-07-18 10:00', '2026-07-30 18:00', NULL, '2026-07', 18, 6.5, 260, '许清河', '沈南乔', '顾言', '结构设计', '进行中', 42, '', '[{"id":"demo-pm-3","date":"2026-07-19","start":"10:00","end":"13:30","note":"盘点现有入口与角色差异"},{"id":"demo-pm-4","date":"2026-07-23","start":"14:00","end":"17:00","note":"完成第一版站点地图"}]', '[]', 1, '2026-07-18 09:48', '2026-07-23 17:00'),
('860000003', 'demo', '新用户七日激活计划', '围绕首次创建、首次协作和首次回顾设计七日触达节奏，并设置对照组验证真实增量。', '用户运营', '2026-06-16 09:00', '2026-06-25 18:00', '2026-06-25 17:20', '2026-06', 12, 11, 260, '苏晚晴', '陆遥', '孟溪', '活动复盘', '已验收', 100, '触达已完成首轮验证，激活率提升 8.6%。', '[{"id":"demo-ops-1","date":"2026-06-17","start":"09:00","end":"15:00","note":"完成分层策略和触达脚本"},{"id":"demo-ops-2","date":"2026-06-24","start":"13:00","end":"18:00","note":"复盘对照组数据并提交结论","isAcceptanceProgress":true}]', '[]', 1, '2026-06-16 08:55', '2026-06-25 17:20'),
('860000004', 'demo', '沉默用户召回实验', '筛选 30 天未活跃用户，设计三组差异化召回内容，并跟踪回访与关键动作完成率。', '用户运营', '2026-07-11 10:30', '2026-07-24 18:00', NULL, '2026-07', 10, 4.5, 260, '苏晚晴', '程木', '孟溪', '等待素材', '挂起', 38, '', '[{"id":"demo-ops-3","date":"2026-07-12","start":"10:30","end":"15:00","note":"完成用户分群与第一版召回文案"}]', '[{"id":"demo-wait-1","date":"2026-07-18","start":"16:20","end":"16:20","note":"等待法务确认优惠券表达","reason":"等待补充资料"}]', 1, '2026-07-11 10:12', '2026-07-18 16:20'),
('860000005', 'demo', '星澜 App 季度留存分析', '分析不同获客渠道的次日、7 日和 30 日留存，识别关键流失节点并给出实验建议。', '数据分析', '2026-06-08 09:30', '2026-06-19 18:00', '2026-06-19 15:45', '2026-06', 14, 12.5, 260, '闻舟', '唐梨', '江屿', '结论交付', '已验收', 100, '数据口径复核通过，结论已进入增长实验排期。', '[{"id":"demo-data-1","date":"2026-06-09","start":"09:30","end":"17:30","note":"完成数据清洗、分群与留存计算"},{"id":"demo-data-2","date":"2026-06-18","start":"13:30","end":"18:00","note":"完成洞察报告与复核","isAcceptanceProgress":true}]', '[]', 1, '2026-06-08 09:18', '2026-06-19 15:45'),
('860000006', 'demo', '春季增长活动渠道漏斗', '统一四个投放渠道的曝光、点击、注册和激活口径，输出可复用漏斗表与预算建议。', '数据分析', '2026-07-14 09:00', '2026-07-25 18:00', NULL, '2026-07', 11, 9.25, 260, '闻舟', '陈望', '江屿', '等待验收', '待验收', 92, '', '[{"id":"demo-data-3","date":"2026-07-15","start":"09:00","end":"16:00","note":"完成渠道数据对齐与异常值处理"},{"id":"demo-data-4","date":"2026-07-24","start":"14:00","end":"16:15","note":"提交漏斗分析和预算建议","isAcceptanceProgress":true}]', '[]', 1, '2026-07-14 08:52', '2026-07-24 16:15'),
('860000007', 'demo', '企业知识库 RAG 评测框架', '建立覆盖检索、引用、拒答与冲突信息处理的评测集，支持模型版本之间的稳定对比。', 'AI 研究员', '2026-07-05 10:00', '2026-07-29 18:00', NULL, '2026-07', 28, 18, 260, '季衡', '夏沐', '宋启', '基线评测', '进行中', 68, '', '[{"id":"demo-ai-1","date":"2026-07-07","start":"10:00","end":"18:00","note":"定义评测维度并整理 60 条样本"},{"id":"demo-ai-2","date":"2026-07-21","start":"09:30","end":"19:30","note":"完成首轮基线运行与错误归因"}]', '[]', 1, '2026-07-05 09:44', '2026-07-21 19:30'),
('860000008', 'demo', '提示词鲁棒性对照实验', '验证角色提示、格式约束和工具失败情况下的输出稳定性，形成上线前检查清单。', 'AI 研究员', '2026-06-10 09:30', '2026-06-24 18:00', '2026-06-24 17:10', '2026-06', 20, 16.5, 260, '季衡', '乔安', '宋启', '实验归档', '已验收', 100, '评测记录完整，三个高风险模式均已加入回归集。', '[{"id":"demo-ai-3","date":"2026-06-11","start":"09:30","end":"17:30","note":"搭建变量矩阵和自动评分脚本"},{"id":"demo-ai-4","date":"2026-06-23","start":"09:30","end":"18:00","note":"完成对照实验与风险清单","isAcceptanceProgress":true}]', '[]', 1, '2026-06-10 09:20', '2026-06-24 17:10'),
('860000009', 'demo', '研发岗位招聘漏斗复盘', '复盘前端、后端与数据岗位从简历到 Offer 的转化，定位筛选标准和面试协作问题。', 'HR / 人力资源', '2026-06-20 09:00', '2026-06-30 18:00', '2026-06-30 16:30', '2026-06', 12, 10, 260, '白露', '贺青', '姚宁', '复盘完成', '已验收', 100, '招聘团队已采用统一评分卡和候选人沟通节点。', '[{"id":"demo-hr-1","date":"2026-06-22","start":"09:00","end":"15:00","note":"完成漏斗统计和岗位差异分析"},{"id":"demo-hr-2","date":"2026-06-29","start":"13:00","end":"17:00","note":"组织复盘会并确认改进动作","isAcceptanceProgress":true}]', '[]', 1, '2026-06-20 08:40', '2026-06-30 16:30'),
('860000010', 'demo', '新经理 30 天融入计划', '为首次带团队的经理设计 30 天融入路径，包含关键会谈、团队诊断和反馈检查点。', 'HR / 人力资源', '2026-07-25 14:00', '2026-08-08 18:00', NULL, '2026-07', 14, 0, 260, '白露', '叶川', '姚宁', '待启动', '计划中', 0, '', '[]', '[]', 1, '2026-07-25 13:42', '2026-07-25 13:42'),
